<script>
  import { onMount } from "svelte";

  export let pageHeight;

  const uptime = Date.now();

  let terminalPath = " client@debian-0:~$ ";
  let blinkingBar = "_";
  let terminalWriting = JSON.parse(JSON.stringify(terminalPath));
  let terminalContent;
  let terminalLoading;
  let terminalAttached;
  let terminal;
  let inputterminal;
  let historyPointer = null;

  const technologies = {
    Languages: ["Javascript", "Python", "Bash", "C++"],
    Databases: ["MongoDB", "Redis", "Cassandra", "SQLite", "MySQL"],
    "Developing Stack & Tools": [
      "Git | Github",
      "Docker",
      "Insomnia",
      "Linux",
      "Wireshark",
      "NumPy",
      "Svelte",
      "NGINX",
      "VirtualBox | VMWare",
    ],
  };

  const history = [];

  const filterKeys = [
    "Control",
    "Alt",
    "CapsLock",
    "Shift",
    "Insert",
    "PageUp",
    "PageDown",
    "Home",
    "End",
    "Delete",
    "Tab",
    "Escape",
    "AudioVolumeDown",
    "AudioVolumeUp",
    "F1",
    "F2",
    "F3",
    "F4",
    "F5",
    "F6",
    "F7",
    "F8",
    "F9",
    "F10",
    "F11",
    "F12",
    "ArrowRight",
    "ArrowLeft",
  ];

  onMount(() => {
    terminalContent = document.getElementById("terminal-body-content");
    terminal = document.getElementById("terminal-body");
    inputterminal = document.getElementById("input");

    terminalContent.innerHTML +=
      terminalPath +
      " help" +
      "<br>" +
      `<span class="tn">help</span> <span class="td">Displays this help message, showing the available commands.</span>` +
      "<br>" +
      `<span class="tn">technologies</span> <span class="td">Displays a list of technologies frecuently used by root user.</span>` +
      "<br>" +
      `<span class="tn">app</span> <span class="td">Displays a list of apps or projects created by root user.</span>` +
      "<br>" +
      `<span class="tn">bash</span> <span class="td">sh-compatible command language interpreter that executes commands read from the standard input or from a file.</span>` +
      "<br>" +
      `<span class="tn">whoami</span> <span class="td">Shows in console the current logged-in user.</span>` +
      "<br>" +
      `<span class="tn">ls</span> <span class="td">Displays files and directories in your current directory.</span>` +
      "<br>" +
      `<span class="tn">inxi</span> <span class="td">Show information about your system.</span>` +
      "<br>" +
      `<span class="tn">echo</span> <span class="td">Display message in the console.</span>` +
      "<br>" +
      `<span class="tn">history</span> <span class="td">Display a list of the commands in the history.</span>` +
      "<br>" +
      `<span class="tn">clear</span> <span class="td">Clean the console.</span>` +
      "<br>" +
      `<span class="tn">neofetch</span> <span class="td">Displays information about your operating system, software and hardware.</span>` +
      "<br>" +
      `<span class="tn">pwd</span> <span class="td">Prints the current directory.</span>` +
      "<br><br>";

    terminal.addEventListener(
      "scroll",
      (_) => (inputterminal.style.minHeight = terminal.scrollHeight + "px")
    );
  });

  window.addEventListener("scroll", (e) => {
    terminalAttached = false;
  });

  setInterval((_) => {
    blinkingBar = "  ";
    setTimeout((_) => (blinkingBar = "_"), 300);
  }, 1000);

  let writingSudo = false;
  let sudoAttempts = 0;

  const manageKey = async (e) => {
    const isMobile = e.key === "Unidentified";

    if (isMobile)
      return alert(
        "Console not allowed on mobile devices, please go to a desktop device and try it out!"
      );

    const key = e.key;

    const keyAllowed = !filterKeys.includes(key);

    if (keyAllowed) {
      e.preventDefault();

      if (!terminalLoading) {
        switch (key) {
          case "Backspace":
            terminalWriting =
              terminalWriting.length > terminalPath.length
                ? terminalWriting.slice(0, -1)
                : terminalWriting;
            break;

          case "Enter":
            terminalLoading = true;
            terminal.scrollBy(0, 10 * 100);
            terminalAttached = true;

            terminalContent.innerHTML += terminalWriting + "<br>";
            const tempWrited = terminalWriting;
            terminalWriting = "";

            await manageCMD(
              writingSudo
                ? terminalPath + `sudo T${tempWrited.length}`
                : tempWrited
            );
            if (!writingSudo) terminalWriting = terminalPath;

            if (terminalAttached) terminal.scrollBy(0, 100_000_000);

            historyPointer = history.length;
            terminalLoading = false;
            break;

          case "ArrowUp":
            if (!history.length) break;

            if (historyPointer) historyPointer--;
            else if (historyPointer === 0) return 0;
            else historyPointer = history.length;

            terminalWriting = terminalPath + history[historyPointer];
            break;

          case "ArrowDown":
            if (!history.length) break;

            const tempRelations = [history.length - 1, history.length];

            if (tempRelations.includes(historyPointer)) {
              terminalWriting = terminalPath;
              historyPointer = history.length;

              break;
            }

            if (historyPointer || historyPointer === 0) historyPointer++;
            else historyPointer = history.length - 1;

            terminalWriting = terminalPath + history[historyPointer];

            break;

          default:
            terminalWriting += writingSudo ? "*" : key;
        }
      }
    }
  };

  function sendEmailShell() {
    const anchor = document.createElement("a");

    anchor.href =
      "mailto:guidomoran.ap@gmail.com?subject=Contact%20%7C%20Networking&body=Dear%20Guido%2C%0A%0A%5B...%5D%0A%0A";

    anchor.target = "_blank";

    anchor.click();
  }

  async function getPublicIpShell() {
    const result = await fetch("https://api.ipify.org")
      .then((res) => res.text())
      .catch(() => 0);

    terminalContent.innerHTML +=
      (result || "Error trying to get public ip.") + "<br><br>";
  }

  const manageCMD = async (writed) => {
    writed = writed.slice(terminalPath.length, writed.length);

    if (!writingSudo) history.push(writed);

    switch (writed.split(" ")[0]) {
      case "help":
        terminalContent.innerHTML +=
          `<span class="tn">help</span> <span class="td">Displays this help message, showing the available commands.</span>` +
          "<br>" +
          `<span class="tn">technologies</span> <span class="td">Displays a list of technologies frecuently used by root user.</span>` +
          "<br>" +
          `<span class="tn">app</span> <span class="td">Displays a list of apps or projects created by root user.</span>` +
          "<br>" +
          `<span class="tn">bash</span> <span class="td">sh-compatible command language interpreter that executes commands read from the standard input or from a file.</span>` +
          "<br>" +
          `<span class="tn">whoami</span> <span class="td">Shows in console the current logged-in user.</span>` +
          "<br>" +
          `<span class="tn">ls</span> <span class="td">Displays files and directories in your current directory.</span>` +
          "<br>" +
          `<span class="tn">inxi</span> <span class="td">Show information about your system.</span>` +
          "<br>" +
          `<span class="tn">echo</span> <span class="td">Display message in the console.</span>` +
          "<br>" +
          `<span class="tn">history</span> <span class="td">Display a list of the commands in the history.</span>` +
          "<br>" +
          `<span class="tn">clear</span> <span class="td">Clean the console.</span>` +
          "<br>" +
          `<span class="tn">neofetch</span> <span class="td">Displays information about your operating system, software and hardware.</span>` +
          "<br>" +
          `<span class="tn">pwd</span> <span class="td">Prints the current directory.</span>` +
          "<br><br>";
        break;

      case "":
        terminalContent.innerHTML += "<br>";
        break;

      case "clear":
        inputterminal.style.minHeight = "100%";
        terminalContent.innerHTML = "";
        break;

      case "cls":
        inputterminal.style.minHeight = "100%";
        terminalContent.innerHTML = "";
        break;

      case "whoami":
        terminalContent.innerHTML += "client" + "<br><br>";
        break;

      case "inxi":
        terminalContent.innerHTML += navigator.userAgent + "<br><br>";
        break;

      case "neofetch":
        const logo = `
         _,met$$$$$gg.<br>
      ,g$$$$$$$$$$$$$$$P.<br>
    ,g$$P""       """Y$$.".<br>
  ,$$P'              \`$$$.<br>
',$$P       ,ggs.     \`$$b:<br>
\`d$$'     ,$P"'   <hl>.</hl>    $$$<br>
 $$P       d$'     <hl>,</hl>    $$P<br>
 $$:       $$.   <hl>-</hl>    ,d$$'<br>
 $$;       Y$b._   _,d$P'<br>
 Y$$.     <hl>\`.</hl>\`"Y$$$$P"'<br>
 \`$$b       <hl>"-.__</hl><br>
  \`Y$$b<br>
   \`Y$$.<br>
      \`$$b.<br>
        \`Y$$b.<br>
          \`"Y$b._<br>
             \`"""<br>`;

        const output = `
        <br>
        <span class="neofetch">
          <span>
            <code>
            <b>
              ${logo.replaceAll(" ", "&nbsp;")}
            </b>
            </code>
          </span>
          <span class="neo-description">
            <span class='neo-hl'>client</span>@<span class='neo-hl'>debian-0</span><br>
            <span style='font-size: 1.33rem; font-weight: lighter;'>${"-".repeat(terminalPath.length)}</span><br>
            <span class='neo-hl'>OS</span>&nbsp;:&nbsp;&nbsp;Debian GNU/Linux 10 (bookworm) x86_64<br>
            <span class='neo-hl'>Host</span>&nbsp;:&nbsp;&nbsp;B550-F GAMING<br>
            <span class='neo-hl'>Kernel</span>&nbsp;:&nbsp;&nbsp;6.10.6-amd64 <br>
            <span class='neo-hl'>Uptime</span>&nbsp;:&nbsp;&nbsp;${String(Date.now() - uptime).slice(0, -3)}s<br>
            <span class='neo-hl'>Packages</span>&nbsp;:&nbsp;&nbsp;222 (dpkg)<br>
            <span class='neo-hl'>Shell</span>&nbsp;:&nbsp;&nbsp;bash 5.2.15<br>
            <span class='neo-hl'>Resolution</span>&nbsp;:&nbsp;&nbsp;${window.innerWidth}x${window.innerHeight}<br>
            <span class='neo-hl'>Theme</span>&nbsp;:&nbsp;&nbsp;Xfce [GTK2], Adwaita [GTK3]<br>
            <span class='neo-hl'>CPU</span>&nbsp;:&nbsp;&nbsp;AMD Ryzen 5 3450U with Radeon Vega Mobile Gfx (8) @ 2.100GHz<br>
            <span class='neo-hl'>GPU</span>&nbsp;:&nbsp;&nbsp;AMD ATI Radeon Vega Series / Radeon Vega Mobile Series<br>
            <span class='neo-hl'>Explorer</span>&nbsp;:&nbsp;&nbsp;${navigator.vendor}<br>
            <span class='neo-hl'>Memory</span>&nbsp;:&nbsp;&nbsp;28${Math.floor(Math.random() * 9)}${Math.floor(Math.random() * 9)}${Math.floor(Math.random() * 9)}MiB / 32256MiB<br>
          </span>
          <br>
        </span>
        <br>`;

        terminalContent.innerHTML += output;

        break;

      case "technologies":
        for (const k of Object.keys(technologies)) {
          terminalContent.innerHTML += `${k}<br>`;

          for (const t of technologies[k]) {
            await new Promise((resolve) =>
              setTimeout((_) => {
                terminalContent.innerHTML += `<span class="ts">${t}</span><br>`;
                if (terminalAttached) terminal.scrollBy(0, 100_000_000);

                return resolve();
              }, 200)
            );
          }

          await new Promise((resolve) => setTimeout(resolve, 600));
          terminalContent.innerHTML += "<br>";
        }

        break;

      case "app":
        if (writed.slice(0, 10) === "app --open") {
          await new Promise((resolve) =>
            setTimeout(async (_) => {
              const apps = await fetch(
                "https://api.github.com/users/Guidoow/repos"
              )
                .then((res) => res.json())
                .catch((err) => 0);

              if (apps) {
                const cleanApps = Object.values(apps).filter(
                  (project) => project.name !== "Guidoow"
                );

                const appNames = Object.values(apps).map((p) =>
                  p.name.toLowerCase()
                );

                const leftover = writed.slice(11).trim();

                if (appNames.includes(leftover.toLowerCase())) {
                  open(
                    cleanApps.find(
                      (p) => p.name.toLowerCase() === leftover.toLowerCase()
                    ).html_url
                  );
                } else {
                  open("https://github.com/Guidoow");
                }
              } else {
                open("https://github.com/Guidoow");
              }

              resolve();
            })
          );

          terminalContent.innerHTML += "<br>";
          break;
        } else {
          terminalContent.innerHTML += "Retrieving data from disk &nbsp;";

          const interval = setInterval(() => {
            terminalContent.innerHTML += ".";
            if (terminalAttached) terminal.scrollBy(0, 100_000_000);
          }, 600);

          await new Promise((solv) =>
            setTimeout(async (_) => {
              clearInterval(interval);
              terminalContent.innerHTML += "<br><br>";
              if (terminalAttached) terminal.scrollBy(0, 100_000_000);
              return solv();
            }, 2000)
          );

          await new Promise((resolve) =>
            setTimeout(async (_) => {
              const apps = await fetch(
                "https://api.github.com/users/Guidoow/repos"
              )
                .then((res) => res.json())
                .catch(() => 0);

              if (apps) {
                terminalContent.innerHTML = terminalContent.innerHTML.slice(
                  0,
                  -43
                );

                terminalContent.innerHTML += `use '--open' to open github website. <br><br>`;
                terminalContent.innerHTML += `use '--open repo_name' to open repository website. <br><br>`;

                terminalContent.innerHTML += `<span class="tn">NAME</span>`;
                terminalContent.innerHTML += `<span class="ts">LANG</span>`;
                terminalContent.innerHTML += `<span class="td">DESC</span>`;
                terminalContent.innerHTML += "<br>";
                if (terminalAttached) terminal.scrollBy(0, 100_000_000);

                let counter = 0;

                const cleanApps = apps.filter(
                  (project) => project.name !== "Guidoow"
                );

                for (let i = 0; i < cleanApps.length; i++) {
                  await new Promise((solve) => {
                    const project = cleanApps[i];

                    setTimeout(() => {
                      terminalContent.innerHTML += `<span class="tn">[${project.name}]</span>`;
                      terminalContent.innerHTML += `<span class="ts">${project.language}</span><span class="td">${project.description}</span>`;
                      terminalContent.innerHTML += "<br>";

                      if (i === cleanApps.length - 1)
                        terminalContent.innerHTML += "<br>";
                      if (terminalAttached) terminal.scrollBy(0, 100_000_000);

                      solve();
                    }, counter);
                  });

                  counter += 500;
                }

                if (terminalAttached) terminal.scrollBy(0, 100_000_000);

                return resolve();
              } else {
                setTimeout(() => {
                  terminalContent.innerHTML +=
                    "An error occurs when trying to list the applications. It seems like your disc is corrupted. <br> <br>";
                  if (terminalAttached) terminal.scrollBy(0, 100_000_000);

                  return resolve();
                }, 500);
              }
            }, 500)
          );

          break;
        }

      case "echo":
        terminalContent.innerHTML += writed.slice(4) + "<br><br>";
        break;

      case "bash":
        const cleanWrited = writed.split(" ").slice(1);

        const commandsMap = {};

        const commands = [
          "send_email",
          ".send_email",
          "./send_email",
          "send_email.sh",
          ".send_email.sh",
          "./send_email.sh",

          "get_public_ip",
          ".get_public_ip",
          "./get_public_ip",
          "get_public_ip.sh",
          ".get_public_ip.sh",
          "./get_public_ip.sh",
        ];

        commandsMap["send_email"] = sendEmailShell;
        commandsMap[".send_email"] = sendEmailShell;
        commandsMap["./send_email"] = sendEmailShell;
        commandsMap["send_email.sh"] = sendEmailShell;
        commandsMap[".send_email.sh"] = sendEmailShell;
        commandsMap["./send_email.sh"] = sendEmailShell;

        commandsMap["get_public_ip"] = getPublicIpShell;
        commandsMap[".get_public_ip"] = getPublicIpShell;
        commandsMap["./get_public_ip"] = getPublicIpShell;
        commandsMap["get_public_ip.sh"] = getPublicIpShell;
        commandsMap[".get_public_ip.sh"] = getPublicIpShell;
        commandsMap["./get_public_ip.sh"] = getPublicIpShell;

        if (!cleanWrited[0]) {
          return (terminalContent.innerHTML +=
            "Executes a bash script. <br>Usage: 'bash bash_file' or 'bash bash_file.sh'. <br><br>");
        }

        if (commands.includes(cleanWrited[0]))
          await new Promise(async (resolve) => {
            await commandsMap[cleanWrited[0]]();

            resolve();
          });
        else
          terminalContent.innerHTML +=
            `bash: ${cleanWrited[0]}: No such file or directory` + "<br><br>";

        break;

      case "send_email.sh":
        sendEmailShell();
        break;

      case "get_public_ip.sh":
        await getPublicIpShell();
        break;

      case "ls":
        terminalContent.innerHTML +=
          [
            "get_public_ip.sh",
            "send_email.sh",
            ".conf",
            ".dev_cache",
            ".profile",
          ].join("&nbsp;&nbsp;&nbsp;&nbsp;") + "<br><br>";
        break;

      case "sudo":
        if (writingSudo) {
          await new Promise((resolve) => {
            sudoAttempts += 1;

            setTimeout(() => {
              console.log(writed);
              console.log(writed.slice(6));
              const asteriskLength = Number(writed.slice(6)) + "<br>".length;

              terminalContent.innerHTML = terminalContent.innerHTML.slice(
                0,
                -asteriskLength
              );

              terminalContent.innerHTML += "<br><br>";
              terminalContent.innerHTML += "Sorry, try again.";

              setTimeout(() => {
                terminalContent.innerHTML += "<br>";
                terminalContent.innerHTML += "[sudo] password for guidoow: ";

                if (sudoAttempts > 1) {
                  writingSudo = false;
                  sudoAttempts = 0;
                  terminalContent.innerHTML += "<br><br>";
                }

                resolve();
              }, 500);
            }, 1500);
          });
        } else {
          writingSudo = true;
          terminalContent.innerHTML += "[sudo] password for guidoow: ";
        }
        break;

      case "apt":
        `apt: Permission denied.` + "<br><br>";

      case "apt-get":
        `apt-get: Permission denied.` + "<br><br>";

      case "cd":
        terminalContent.innerHTML += writed.slice(2)
          ? `cd: ${writed.slice(2)}: Permission denied.` + "<br><br>"
          : "Navigate through directories. <br>Usage: 'cd directory'.<br><br>";

        break;

      case "pwd":
        terminalContent.innerHTML += "/home/guidoow/public" + "<br><br>";
        break;

      case "history":
        history.forEach((cmd) => (terminalContent.innerHTML += cmd + "<br>"));
        break;

      default:
        terminalContent.innerHTML +=
          `${writed.split(" ")[0]}: command not found.` + "<br><br>";
        break;
    }

    return 0;
  };
</script>

