    }
  }

  @keyframes terminal {
    100% {
      -webkit-transform: skewY(0deg) translateX(0px) translateY(0px);
      transform: skewY(0deg) translateX(0px) translateY(0px);
      width: 100vw;
      height: 100vh;
      scale: 1;
      -webkit-box-shadow: 7px 7px 20px 3px rgba(0, 0, 0, 0.4);
      box-shadow: 7px 7px 20px 3px rgba(0, 0, 0, 0.4);
    }
  }

  .terminal > .body {
    color: white;
    -webkit-box-sizing: border-box;
    box-sizing: border-box;
    width: 100%;
    height: 100%;
    background-color: black;
    padding: 0.5rem;
    bottom: 0px;
    overflow: hidden;
    overflow-y: scroll;
    overflow-wrap: break-word;
    scroll-padding: 50px;
    scrollbar-width: thin;
    scrollbar-color: transparent transparent;
    padding-bottom: 3rem;
  }
  .terminal > .body::-webkit-scrollbar {
    width: 6px;
  }

  .terminal > .body::-webkit-scrollbar {
    background-color: transparent;
  }

  .input {
    position: absolute !important;
    background-color: rgba(150, 150, 150, 0.025);
    z-index: 6000;
    color: none;
    border: none;
    margin: 0;
    padding: 0;
    top: 0;
    right: 0;
    bottom: 0;
    left: 0;
    width: 100%;
    height: 100%;
