function getSnaps() {
  const snap = [0];

  const sectionsElement = document.getElementById("sections");
  const nodeHeight = sectionsElement.clientHeight / 3;
  const initSectionHeight =
    document.body.firstElementChild.firstElementChild.clientHeight;
  pageHeight = document.body.clientHeight;

  Array.from(sectionsElement.childNodes)
    .filter((n) => n.nodeType === 1)
    .forEach((node, i) => {
      const secAmount = i + 1;

      const sectionAtHeight =
        initSectionHeight +
        nodeHeight * secAmount -
        ((nodeHeight - node.clientHeight) / 2) * 2;

      let scaledSnap = sectionAtHeight / pageHeight;

      scaledSnap = window.innerWidth < 600 ? scaledSnap * 0.95 : scaledSnap;

      snap.push(scaledSnap);
    });

  // GET FINAL SECTION
  const main = document.getElementsByTagName("main")[0];

  let childs = Array.from(main.childNodes);

  childs = childs.filter(
    (child) =>
      child.classList && Array.from(child.classList).includes("pin-spacer")
  );

  const finalSection = childs[1];

  snap.push(
    (pageHeight - finalSection.clientHeight + window.innerHeight) / pageHeight
  );

  snap.push(1);

  return snap;
}

let enableScroll;
let initiallyEnabledScroll = false;

function scrollDownAnimationFunction() {
  if (!initiallyEnabledScroll) {
    enableScroll();
    initiallyEnabledScroll = true;
  }

  gsap
    .timeline()
    .from("#scroll-indicator", {
      duration: 1,
      y: 0,
      scale: 1,
      stagger: 0.01,
    })
    .to("#scroll-indicator", {
      duration: 0.5,
      y: 25,
      scale: 1.25,
      stagger: 0.01,
    })
    .to("#scroll-indicator", {
      duration: 0.9,
      y: 0,
      scale: 1,
      stagger: 0.01,
      onComplete: scrollDownAnimationFunction,
    });
}

let pageHeight = document.body.clientHeight;

gsap.registerPlugin(ScrollTrigger);

export default function (funEnableScroll) {
  enableScroll = funEnableScroll;

  gsap.to("#initial-bg", {
    scrollTrigger: {
      trigger: "#initial-bg",
      start: "clamp(top top)",
      end: "clamp(+=4600)",
      pinSpacing: true,
      pin: true,
    },
    stagger: 0.1,
  });

  const sectionsElement = document.getElementById("sections");

  Array.from(sectionsElement.childNodes)
    .filter((n) => n.nodeType === 1)
    .forEach((node, i) => {
      gsap.to("#section" + Number(i + 1), {
        scrollTrigger: {
          trigger: "#section" + Number(i + 1),
          start: "top top",
          end: "+=5000",
          pinSpacing: true,
          pin: true,
        },
      });

      const filteredChilds = Array.from(node.childNodes).filter(
        (n) => n.nodeType === 1
      );

      const title = filteredChilds[0];
      const content = filteredChilds[2];

      const titleText = new SplitType(title, { types: "chars" });

      gsap.from(titleText.chars, {
        scrollTrigger: {
          trigger: title,
          start: "clamp(top 80%)",
          end: "clamp(+=500)",
        },
        y: 50,
        opacity: 0.01,
        stagger: 0.015,
      });

      const contentText = new SplitType(content);

      gsap.from(contentText.chars, {
        scrollTrigger: {
          trigger: title,
          start: "clamp(+=1000)",
          end: "clamp(+=500)",
        },
        x: 100,
        opacity: 0,
        stagger: 0.004,
      });
    });

  gsap.to(".section-laptop", {
    scrollTrigger: {
      trigger: ".section-laptop",
      start: "clamp(top top)",
      end: "+=" + window.innerHeight * 2,
      pinSpacing: true,
      pin: true,
      scrub: false,
    },
    stagger: 0.005,
  });

  const snapTo = getSnaps();

  ScrollTrigger.create({
    trigger: "body",
    start: "top top",
    end: "bottom bottom",
    snap: {
      snapTo,
      delay: 0,
      duration: 4,
      ease: "power1.inOut",
    },
  });

  gsap
    .timeline()
    .from("#initial-bg", {
      backgroundSize: `${window.innerWidth}px ${window.innerWidth}px`,
      opacity: 0.1,
      duration: 3,
    })
    .from("canvas", {
      opacity: 0,
    })
    .from("#layout-name", {
      opacity: 0,
      y: `-${window.innerHeight}`,
    })
    .to("#layout-name", {
      fontSize: "122",
      opacity: 1,
      duration: 1,
    })
    .to("#layout-name", {
      fontSize: "20",
      opacity: 1,
    })
    .from("#mid span", {
      y: `${window.innerHeight} * 2`,
      duration: 0.5,
    })
    .from("#bottom-bar", {
      y: "100px",
      height: 0,
      duration: 0.15,
    })
    .from("#layout-softwaredev", {
      y: `${window.innerHeight * 10}`,
      duration: 1,
    })
    .from(["#right span", "#left span"], {
      y: `${window.innerHeight} * 2`,
      duration: 0.75,
    })
    .from(["#scroll-indicator-mouse", "#scroll-indicator"], {
      y: 1000,
      opacity: 0.2,
      duration: 0.75,
      onComplete: scrollDownAnimationFunction,
    })
    .to(
      [
        "#layout-softwaredev",
        "#layout-name",
        "#scroll-indicator-mouse",
        "#scroll-indicator",
      ],
      {
        scrollTrigger: {
          trigger: "main",
          start: "top top",
          end: `clamp(+=${window.innerHeight})`,
          scrub: 1,
        },
        opacity: 0,
      }
    );

  return [snapTo, pageHeight];
}
