    img.src = "/assets/server.nobg.png";

    img.onload = async function () {
      const e = document.getElementById("/server.nobg.png");

      e.style.width = img.width;
      e.style.height = img.height;
    };
  }

  onMount(() => {
    loadImage();
  });
</script>

