    let img = new Image();

    img.src = "/assets/aim.nobg.png";

    img.onload = async function () {
      const e = document.getElementById("/aim.nobg.png");

      e.style.width = img.width;
      e.style.height = img.height;
    };
  }

  onMount(() => {
    loadImage();
  });
</script>

