export default () => {
  const canvas = document.getElementById("canvas");
  const ctx = canvas.getContext("2d");
  canvas.width = window.innerWidth;
  canvas.height = window.innerHeight;

  const characters = "ᔑリʖᓵ!¡ᑑᒷ∷⎓ᓭ⊣ℸ⍑⚍╎⍊⋮∴ꖌꖎ||ᒲ⨅";
  const particlesArray = [];
  const numberOfParticles = 64 * 2;

  class Particle {
    constructor() {
      this.x = Math.random() * canvas.width;
      this.y = Math.random() * canvas.height;
      this.speedY = Math.random() * -3 - 0.5;
      this.speedX = (Math.random() * 2 - 1) / 2.4;
      this.size = Math.random() * 20 + 6;
      this.character = characters.charAt(
        Math.floor(Math.random() * characters.length)
      );
      this.lifetime = Math.round(Math.random() * 300);
      this.opacity = 0;
    }

    update() {
      this.x += this.speedX;
      this.y += this.speedY;
      this.lifetime--;

      if (this.x > canvas.width) this.x = 0;
      if (this.x < 0) this.x = canvas.width;
      if (this.y > canvas.height) this.y = 0;
      if (this.y < 0) this.y = canvas.height;
    }

    draw() {
      ctx.fillStyle = "#424242";
      ctx.font = `${this.size}px Arial`;
      ctx.fillText(this.character, this.x, this.y);
    }

    refresh(i) {
      particlesArray[i] = new Particle();
    }
  }

  function init() {
    for (let i = 0; i < numberOfParticles; i++) {
      particlesArray.push(new Particle());
    }
  }

  function animate() {
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    for (let i = 0; i < particlesArray.length; i++) {
      particlesArray[i].update();
      particlesArray[i].draw();

      if (particlesArray[i].lifetime <= 0) particlesArray[i].refresh(i);
    }
    requestAnimationFrame(animate);
  }

  init();
  animate();

  window.addEventListener("resize", function () {
    canvas.width = window.innerWidth;
    canvas.height = window.innerHeight;
    particlesArray.length = 0;
    init();
  });
};
