<script>
  import { onMount } from "svelte";

  const containerElemMap = {
    mid: undefined,
    right: undefined,
    left: undefined,
  };
  const imageElemMap = { mid: undefined, right: undefined, left: undefined };

  async function adjustBackground() {
    const names = Object.keys(containerElemMap);

    for (let i = 0; i < names.length; i++) {
      let span = document.getElementById(names[i]);

      containerElemMap[names[i]] = span;

      await loadImage(names[i]);
    }
  }

  async function loadImage(name) {
    return new Promise((resolve) => {
      let img = new Image();

      img.src = "/assets/" + name + ".png";
      img.onload = async function () {
        adjustSize(name);

        return resolve(1);
      };

      imageElemMap[name] = img;
    });
  }

  function adjustSize(name) {
    return new Promise((resolve) => {
      containerElemMap[name].firstChild.style.opacity = 1;
      containerElemMap[name].firstChild.style.backgroundImage =
        `url(/assets/${name}.png)`;

      const needsReduction = window.innerWidth < 600;
      const screenHeight = window.innerHeight;
      const screenWidth = window.innerWidth;

      const reductionCalc =
        screenWidth / (imageElemMap[name].width * (name === "mid" ? 1 : 1.15));

      let scaledWidth =
        ((imageElemMap[name].width * screenHeight) /
          imageElemMap[name].height) *
        (needsReduction ? reductionCalc : 1);

      let scaledHeight = needsReduction
        ? screenHeight * reductionCalc
        : screenHeight;

      if (name === "mid") {
        const childNodes = containerElemMap[name].childNodes;

        for (let l = 0; l < childNodes.length; l++) {
          const node = childNodes[l];

          if (node.nodeType !== 1) continue;

          node.style.height = scaledHeight + "px";
          node.style.width = scaledWidth + "px";
          node.style.opacity = 1;

          if (node.firstChild) {
            node.firstChild.style.height = scaledHeight + "px";
            node.firstChild.style.width = scaledWidth + "px";
            node.firstChild.style.opacity = 1;
          }
        }
      } else {
        let finalWidth = scaledWidth;

        const midRawFullWidth =
          document.getElementById("mid").firstChild.style.width;
        const midClearFullWidth = Number(midRawFullWidth.slice(0, -2));
        const midAdjustedHalfWidth = ((midClearFullWidth / 2) * 10) / 12;
        const allowedMargin = name === "left" ? -20 : -90;
        const rightAdjustment = 20;
        const adjustment = -40;

        const sidePosition =
          screenWidth / 2 - midAdjustedHalfWidth - scaledWidth + adjustment;

        let sideDisplacement =
          sidePosition > allowedMargin ? sidePosition : allowedMargin;

        const storerElement = document.getElementById(name + "Storer");
        const storerElementStyles = getComputedStyle(storerElement);
        const rawDisplacement = storerElementStyles.getPropertyValue(name);
        const displacement = Number(rawDisplacement.slice(0, -2));

        sideDisplacement += displacement || 0;
        if (name === "right") sideDisplacement += rightAdjustment;

        if (
          name === "left" &&
          sideDisplacement + scaledWidth > screenWidth / 2
        ) {
          const width = Number(
            Number(screenWidth / 2) - sideDisplacement
          ).toFixed();

          finalWidth = width > 0 ? width : "0";
        }

        if (
          name === "right" &&
          sideDisplacement + scaledWidth > screenWidth / 2
        ) {
          const width = Number(
            Number(screenWidth / 2) - sideDisplacement
          ).toFixed();

          finalWidth = width > 0 ? width : "0";
        }

        const childNodes = containerElemMap[name].childNodes;

        for (let l = 0; l < childNodes.length; l++) {
          const node = childNodes[l];

          if (node.nodeType !== 1) continue;

          node.style.height = scaledHeight + "px";
          node.style.width = finalWidth + "px";
          node.style.opacity = 1;
          node.style[name] = sideDisplacement + "px";
          if (node.firstChild) {
            node.firstChild.style.height = scaledHeight + "px";
            node.firstChild.style.width = scaledWidth + "px";

            node.firstChild.style.opacity = 1;
          }
        }
      }

      return resolve(1);
    });
  }

  async function adjustImagesSize() {
    const names = Object.keys(containerElemMap);

    for (let i = 0; i < names.length; i++) {
      await adjustSize(names[i]);
    }
  }

  window.addEventListener("resize", () => {
    setTimeout(adjustImagesSize, 100);
    setTimeout(adjustImagesSize, 500);
  });

  window.addEventListener("scroll", () => {
    setTimeout(adjustImagesSize, 100);
    setTimeout(adjustImagesSize, 500);
  });

  document.addEventListener("DOMContentLoaded", adjustBackground);
  onMount(adjustBackground);
</script>

