<script>
  import Layout from "./Layout.svelte";
  import Sections from "./Sections.svelte";
  import InitialPage from "./InitPage.svelte";
  import Laptop from "./Laptop.svelte";
  import Particles from "./Particles";
  import GSAPManager from "./GSAPManager";
  import { onMount } from "svelte";
  import BottomBar from "./BottomBar.svelte";

  function isMobile() {
    if (navigator.userAgentData) {
      const deviceType = navigator.userAgentData.mobile;
      return deviceType === true;
    } else {
      const userAgent = navigator.userAgent;
      const mobileRegex = /Android|iPhone|iPad|iPod|BlackBerry|Windows Phone/i;
      return mobileRegex.test(userAgent);
    }
  }

  var keys = { 37: 1, 38: 1, 39: 1, 40: 1 };

  function preventDefault(e) {
    e.preventDefault();
  }

  function preventDefaultForScrollKeys(e) {
    if (keys[e.keyCode]) {
      preventDefault(e);
      return false;
    }
  }

  // modern Chrome requires { passive: false } when adding event
  var supportsPassive = false;
  try {
    window.addEventListener(
      "test",
      null,
      Object.defineProperty({}, "passive", {
        get: function () {
          supportsPassive = true;
        },
      })
    );
  } catch (e) {}

  var wheelOpt = supportsPassive ? { passive: false } : false;
  var wheelEvent =
    "onwheel" in document.createElement("div") ? "wheel" : "mousewheel";

  function disableScroll() {
    window.addEventListener("DOMMouseScroll", preventDefault, false); // older FF
    window.addEventListener(wheelEvent, preventDefault, wheelOpt); // modern desktop
    window.addEventListener("touchmove", preventDefault, wheelOpt); // mobile
    window.addEventListener("keydown", preventDefaultForScrollKeys, false);

    window.document.body.setAttribute("data-lenis-prevent", "");
  }

  function enableScroll() {
    window.removeEventListener("DOMMouseScroll", preventDefault, false);
    window.removeEventListener(wheelEvent, preventDefault, wheelOpt);
    window.removeEventListener("touchmove", preventDefault, wheelOpt);
    window.removeEventListener("keydown", preventDefaultForScrollKeys, false);

    window.document.body.removeAttribute("data-lenis-prevent");
  }

  window.addEventListener("resize", (e) => {
    if (!isMobile()) location.reload();
  });

  const lenis = new Lenis({
    lerp: 0.9,
    duration: 0.2,
  });

  function raf(time) {
    lenis.raf(time);
    requestAnimationFrame(raf);
  }

  requestAnimationFrame(raf);

  let pageHeight = document.body.clientHeight;
  let snapTo = [];

  disableScroll();

  onMount(() => {
    window.scrollTo(0, 0);
    setTimeout(() => {
      window.scrollTo(0, 0);
      setTimeout(() => {
        window.scrollTo(0, 0);
        setTimeout(() => {
          window.scrollTo(0, 0);
        }, 200);
      }, 150);
    }, 150);

    Particles();
    [snapTo, pageHeight] = GSAPManager(enableScroll);
  });
</script>

<main>
  <InitialPage />

  <canvas id="canvas" />

  <Sections />

  <Laptop {pageHeight} />

  <BottomBar {snapTo} {pageHeight} />
</main>

<Layout />

<style>
  canvas {
    display: block;
    position: fixed;
    top: 0;
    left: 0;
    width: 100%;
    height: calc(100vh);
    z-index: 0;
  }
</style>
